#include "overlay_window.hpp"
#include "x11_utils.hpp"

#include <X11/extensions/shape.h>
#include <cairo/cairo-xlib.h>

#include <cmath>
#include <fstream>
#include <iostream>

namespace {

// Fallback crosshair canvas size in pixels (square), and matching geometry
// shared between the auto-generated crosshair.svg and the last-resort
// programmatic Cairo drawing below. Kept small and unobtrusive so it doesn't
// get in the way during gameplay.
constexpr unsigned int kFallbackSize = 32;
constexpr double kFallbackCenter = kFallbackSize / 2.0; // 16
constexpr double kFallbackGap = 4.0;
constexpr double kFallbackArm = 9.0;
constexpr double kFallbackOutlineWidth = 4.0;
constexpr double kFallbackInnerWidth = 1.8;
constexpr double kFallbackRingRadius = 2.6;

// Written to <base_dir>/crosshair.svg whenever that file does not exist yet,
// so there is always a real, editable SVG driving the overlay rather than a
// silent, non-inspectable code path. Geometry matches draw_fallback_crosshair()
// below (used only if this generated file somehow fails to load).
constexpr const char* kDefaultCrosshairSvg =
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
    "<!--\n"
    "  Default crosshair, auto-generated by crosshair because no crosshair.svg\n"
    "  was found next to the binary. Replace this file with your own design,\n"
    "  or edit it directly - it is loaded fresh on every startup.\n"
    "-->\n"
    "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" viewBox=\"0 0 32 32\">\n"
    "  <g stroke=\"#000000\" stroke-width=\"4\" stroke-linecap=\"round\" fill=\"none\">\n"
    "    <path d=\"M16,12 L16,3\"/>\n"
    "    <path d=\"M16,20 L16,29\"/>\n"
    "    <path d=\"M12,16 L3,16\"/>\n"
    "    <path d=\"M20,16 L29,16\"/>\n"
    "  </g>\n"
    "  <g stroke=\"#ffffff\" stroke-width=\"1.8\" stroke-linecap=\"round\" fill=\"none\">\n"
    "    <path d=\"M16,12 L16,3\"/>\n"
    "    <path d=\"M16,20 L16,29\"/>\n"
    "    <path d=\"M12,16 L3,16\"/>\n"
    "    <path d=\"M20,16 L29,16\"/>\n"
    "  </g>\n"
    "  <circle cx=\"16\" cy=\"16\" r=\"2.6\" fill=\"none\" stroke=\"#000000\" stroke-width=\"2.4\"/>\n"
    "  <circle cx=\"16\" cy=\"16\" r=\"2.6\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"1\"/>\n"
    "</svg>\n";

void write_default_crosshair_svg(const std::string& path) {
    std::ofstream file(path);
    if (!file) {
        std::cerr << "Warning: could not write default crosshair.svg to " << path << "\n";
        return;
    }
    file << kDefaultCrosshairSvg;
    std::cout << "Generated default crosshair.svg: " << path << "\n";
}

bool find_argb_visual(Display* display, int screen, XVisualInfo& out_info) {
    XVisualInfo template_info;
    template_info.screen = screen;
    template_info.depth = 32;
    template_info.c_class = TrueColor;

    int count = 0;
    XVisualInfo* matches = XGetVisualInfo(
        display, VisualScreenMask | VisualDepthMask | VisualClassMask, &template_info, &count);
    if (matches == nullptr || count == 0) {
        if (matches != nullptr) {
            XFree(matches);
        }
        return false;
    }
    out_info = matches[0];
    XFree(matches);
    return true;
}

} // namespace

OverlayWindow::OverlayWindow(Display* display, int screen, const std::string& svg_path)
    : display_(display),
      screen_(screen),
      window_(0),
      visual_(nullptr),
      colormap_(0),
      surface_(nullptr),
      svg_handle_(nullptr),
      width_(kFallbackSize),
      height_(kFallbackSize) {
    XVisualInfo visual_info;
    const bool have_argb = find_argb_visual(display_, screen_, visual_info);
    if (!have_argb) {
        std::cerr << "Warning: no 32-bit ARGB visual available. The overlay "
                     "background may not be fully transparent (compositing "
                     "may be disabled).\n";
    }

    // Determine crosshair size before creating the window: either from the
    // SVG's intrinsic size, or the fixed fallback canvas size.
    load_svg_or_fallback(svg_path);

    const Rect monitor = get_primary_monitor_geometry(display_, screen_);
    const int x = monitor.x + static_cast<int>(monitor.width - width_) / 2;
    const int y = monitor.y + static_cast<int>(monitor.height - height_) / 2;

    XSetWindowAttributes attrs{};
    attrs.override_redirect = True; // borderless, unmanaged by the WM
    attrs.background_pixel = 0;
    attrs.border_pixel = 0;
    attrs.event_mask = ExposureMask | StructureNotifyMask;

    unsigned long value_mask = CWOverrideRedirect | CWBorderPixel | CWEventMask;

    if (have_argb) {
        visual_ = visual_info.visual;
        colormap_ = XCreateColormap(display_, RootWindow(display_, screen_), visual_, AllocNone);
        attrs.colormap = colormap_;
        value_mask |= CWColormap | CWBackPixel;
        window_ = XCreateWindow(display_, RootWindow(display_, screen_), x, y, width_, height_, 0,
                                 visual_info.depth, InputOutput, visual_, value_mask, &attrs);
    } else {
        visual_ = DefaultVisual(display_, screen_);
        colormap_ = DefaultColormap(display_, screen_);
        value_mask |= CWBackPixel;
        window_ = XCreateWindow(display_, RootWindow(display_, screen_), x, y, width_, height_, 0,
                                 DefaultDepth(display_, screen_), InputOutput, visual_, value_mask,
                                 &attrs);
    }

    XStoreName(display_, window_, "Crosshair");
    set_always_on_top_hints(display_, window_, /*skip_taskbar=*/true);
    make_click_through();

    surface_ = cairo_xlib_surface_create(display_, window_, visual_,
                                          static_cast<int>(width_), static_cast<int>(height_));
    XFlush(display_);
}

void OverlayWindow::show() {
    XMapWindow(display_, window_);
    XFlush(display_);
}

OverlayWindow::~OverlayWindow() {
    if (svg_handle_ != nullptr) {
        g_object_unref(svg_handle_);
    }
    if (surface_ != nullptr) {
        cairo_surface_destroy(surface_);
    }
    if (window_ != 0) {
        XDestroyWindow(display_, window_);
    }
    if (colormap_ != 0 && colormap_ != DefaultColormap(display_, screen_)) {
        XFreeColormap(display_, colormap_);
    }
}

void OverlayWindow::load_svg_or_fallback(const std::string& svg_path) {
    std::ifstream probe(svg_path);
    const bool svg_exists = probe.good();
    probe.close();

    if (!svg_exists) {
        std::cout << "No crosshair.svg found next to the binary; generating a "
                     "default one.\n";
        write_default_crosshair_svg(svg_path);
    }

    GError* error = nullptr;
    RsvgHandle* handle = rsvg_handle_new_from_file(svg_path.c_str(), &error);
    if (handle == nullptr) {
        std::cerr << "Warning: could not load crosshair.svg ("
                  << (error != nullptr ? error->message : "unknown error")
                  << "); using built-in programmatic fallback crosshair instead.\n";
        if (error != nullptr) {
            g_error_free(error);
        }
        svg_handle_ = nullptr;
        width_ = kFallbackSize;
        height_ = kFallbackSize;
        return;
    }

    rsvg_handle_set_dpi(handle, 96.0);

    double svg_width = 0.0;
    double svg_height = 0.0;
    if (!rsvg_handle_get_intrinsic_size_in_pixels(handle, &svg_width, &svg_height) ||
        svg_width <= 0.0 || svg_height <= 0.0) {
        // No physical intrinsic size (e.g. viewBox-only SVG) - fall back to a
        // reasonable on-screen size while still rendering the actual artwork.
        svg_width = kFallbackSize;
        svg_height = kFallbackSize;
    }

    svg_handle_ = handle;
    width_ = static_cast<unsigned int>(std::ceil(svg_width));
    height_ = static_cast<unsigned int>(std::ceil(svg_height));
    std::cout << "Loaded crosshair.svg (" << width_ << "x" << height_ << ")\n";
}

void OverlayWindow::make_click_through() {
    int shape_event_base = 0;
    int shape_error_base = 0;
    if (!XShapeQueryExtension(display_, &shape_event_base, &shape_error_base)) {
        std::cerr << "Warning: X Shape extension not available; the overlay "
                     "will NOT be click-through and will block mouse input.\n";
        return;
    }
    // An empty input shape means the window never receives pointer events;
    // clicks pass straight through to whatever is beneath it.
    XShapeCombineRectangles(display_, window_, ShapeInput, 0, 0, nullptr, 0, ShapeSet, 0);
}

void OverlayWindow::redraw() {
    if (surface_ == nullptr) {
        return;
    }
    cairo_t* cr = cairo_create(surface_);

    // Fully clear to transparent first.
    cairo_save(cr);
    cairo_set_operator(cr, CAIRO_OPERATOR_SOURCE);
    cairo_set_source_rgba(cr, 0, 0, 0, 0);
    cairo_paint(cr);
    cairo_restore(cr);

    if (svg_handle_ != nullptr) {
        RsvgRectangle viewport{0.0, 0.0, static_cast<double>(width_), static_cast<double>(height_)};
        GError* error = nullptr;
        if (!rsvg_handle_render_document(svg_handle_, cr, &viewport, &error)) {
            std::cerr << "Warning: failed to render crosshair.svg ("
                      << (error != nullptr ? error->message : "unknown error")
                      << "); drawing fallback crosshair instead.\n";
            if (error != nullptr) {
                g_error_free(error);
            }
            draw_fallback_crosshair(cr);
        }
    } else {
        draw_fallback_crosshair(cr);
    }

    cairo_destroy(cr);
    cairo_surface_flush(surface_);
    XFlush(display_);
}

void OverlayWindow::draw_fallback_crosshair(cairo_t* cr) const {
    // Only ever invoked at the fixed kFallbackSize canvas, using the same
    // geometry as the auto-generated crosshair.svg (see kDefaultCrosshairSvg).
    const double cx = kFallbackCenter;
    const double cy = kFallbackCenter;
    const double gap = kFallbackGap;
    const double arm = kFallbackArm;
    const double outline_width = kFallbackOutlineWidth;
    const double inner_width = kFallbackInnerWidth;
    const double ring_radius = kFallbackRingRadius;

    auto draw_cross = [&](double line_width, double red, double green, double blue, double alpha) {
        cairo_set_line_width(cr, line_width);
        cairo_set_line_cap(cr, CAIRO_LINE_CAP_ROUND);
        cairo_set_source_rgba(cr, red, green, blue, alpha);

        // Top arm
        cairo_move_to(cr, cx, cy - gap);
        cairo_line_to(cr, cx, cy - gap - arm);
        // Bottom arm
        cairo_move_to(cr, cx, cy + gap);
        cairo_line_to(cr, cx, cy + gap + arm);
        // Left arm
        cairo_move_to(cr, cx - gap, cy);
        cairo_line_to(cr, cx - gap - arm, cy);
        // Right arm
        cairo_move_to(cr, cx + gap, cy);
        cairo_line_to(cr, cx + gap + arm, cy);
        cairo_stroke(cr);
    };

    // Black outline pass first (drawn wider) so the crosshair reads clearly
    // against light backgrounds, then a white pass on top for dark
    // backgrounds - this two-tone outline stays visible on any background
    // color or brightness.
    draw_cross(outline_width, 0.0, 0.0, 0.0, 0.85);
    draw_cross(inner_width, 1.0, 1.0, 1.0, 0.95);

    // A small open center ring, also outlined, for precise aiming reference.
    cairo_set_line_width(cr, outline_width * 0.6);
    cairo_set_source_rgba(cr, 0.0, 0.0, 0.0, 0.85);
    cairo_arc(cr, cx, cy, ring_radius, 0, 2 * M_PI);
    cairo_stroke(cr);

    cairo_set_line_width(cr, inner_width * 0.6);
    cairo_set_source_rgba(cr, 1.0, 1.0, 1.0, 0.95);
    cairo_arc(cr, cx, cy, ring_radius, 0, 2 * M_PI);
    cairo_stroke(cr);
}

void OverlayWindow::raise_to_top() {
    XRaiseWindow(display_, window_);
}
